import sys


def main():
    data = sys.stdin.buffer.read()
    sums = {}
    get = sums.get
    lines = data.split(b'\n')
    for line in lines[1:]:
        if not line:
            continue
        parts = line.split(b',', 2)
        if len(parts) < 3:
            continue
        cat = parts[1]
        v = parts[2].strip()
        dot = v.find(b'.')
        if dot >= 0 and len(v) - dot == 3:
            try:
                c = int(v[:dot]) * 100 + int(v[dot + 1:]) if v[0:1] != b'-' else \
                    int(v[:dot]) * 100 - int(v[dot + 1:])
            except ValueError:
                c = round(float(v) * 100)
        else:
            c = round(float(v) * 100)
        sums[cat] = get(cat, 0) + c
    out = []
    for cat in sorted(sums):
        c = sums[cat]
        sign = '-' if c < 0 else ''
        c = abs(c)
        out.append(b'%s,%s%d.%02d' % (cat, sign.encode(), c // 100, c % 100))
    sys.stdout.buffer.write(b'\n'.join(out) + (b'\n' if out else b''))


main()
